  {
    "@context": "https://schema.org",
    "@type": "FAQPage",
    "mainEntity": [
      {
        "@type": "Question",
        "name": "What is LiDAR data collection?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "It's the capture of LiDAR scans, along with synchronized camera, IMU, and odometry data, in the environments where a robot or vehicle will operate. The data trains and validates 3D perception, mapping, and localization models, and its value depends on calibration and coverage."
        }
      },
      {
        "@type": "Question",
        "name": "How is LiDAR data collection different from 3D point cloud data collection?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "LiDAR collection focuses on range scans from moving robots or vehicles for perception, mapping, and localization. 3D point cloud collection covers near-field and object-level geometry from depth cameras, structured light, photogrammetry, and scanners, often for grasping or simulation assets."
        }
      },
      {
        "@type": "Question",
        "name": "Which LiDAR sensors do you support?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "We work with mechanical spinning sensors, solid-state and flash units, non-repetitive scan sensors, FMCW LiDAR, and 2D safety scanners, on your robots or on our capture rigs. Sensor model, firmware, and configuration are recorded for every session."
        }
      },
      {
        "@type": "Question",
        "name": "How do you handle LiDAR in rain, fog, or dust?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "We treat adverse conditions as coverage targets. Collection is scheduled around the weather and materials your deployment will face, and every frame is tagged with conditions so models can be trained and evaluated per condition."
        }
      },
      {
        "@type": "Question",
        "name": "Do you provide LiDAR annotation as well?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "Yes. After calibration is verified, data goes to our annotation team for 3D bounding boxes, semantic segmentation, and object tracking, labeled against the same specification the collection plan used."
        }
      },
      {
        "@type": "Question",
        "name": "What file formats do you deliver LiDAR data in?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "MCAP or ROS 2 bags, PCD, and LAS or LAZ, with calibration files, per-frame poses, raw timestamps, and a sensor configuration manifest. Custom formats can be supported on request."
        }
      }
    ]
  }
